theme.css:
#wemd{color:#525252;background-color:#FFFFFF;font-family:'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Noto Sans SC', 'Microsoft YaHei', sans-serif;font-size:15px;line-height:1.9;letter-spacing:0.03em;text-align:justify;padding:48px 20px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.6em;text-indent:0}
#wemd h1{font-size:28px;font-weight:700;color:#2B2B2B;margin-top:2.8em;margin-bottom:1.2em;text-align:center}
#wemd h2{font-size:22px;font-weight:700;color:#2B2B2B;margin-top:3em;margin-bottom:1em;text-align:left}
#wemd h3{font-size:17px;font-weight:600;color:#4A5D52;margin-top:2em;margin-bottom:0.8em}
#wemd h4{font-size:15px;font-weight:600;color:#A3A3A3;margin-top:1.5em;margin-bottom:0.5em}
#wemd blockquote{border-left:2px solid #4A5D52;background:#FFFFFF;padding:16px 24px;color:#525252;font-style:normal;margin:1.2em 0}
#wemd code{background-color:#EEF3F0;color:#3D5046;padding:2px 6px;border-radius:2px;font-size:0.9em;font-family:ui-monospace, 'Cascadia Code', 'Fira Code', Menlo, Monaco, Consolas, monospace}
#wemd pre{background:#FAFAFA;border-radius:4px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid #E8E8E8;padding:12px 16px}
#wemd th{background:#EEF3F0}
#wemd tr:nth-child(even){background:#FAFAFA}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:8px}
#wemd li::marker{color:#4A5D52}
#wemd hr{border:0;border-top:1px solid #E8E8E8;margin:3.5em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:2px}
#wemd figcaption{font-size:12px;color:#A3A3A3;text-align:center}
#wemd a{color:#4A5D52;text-decoration:none}
#wemd strong{color:#4A5D52;font-weight:700}
#wemd mark{background:#D6E4DC;padding:2px 4px;border-radius:2px}
